import { ConflictError } from '../errors/DomainError';
import { requireText } from '../shared/RequiredText';
import { DueDate } from './DueDate';
import { TaskStatus } from './TaskStatus';

export interface NewTaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: DueDate;
  status: TaskStatus;
}

export class Task {
  private assignee: string | undefined;

  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: DueDate | undefined,
    private currentStatus: TaskStatus,
  ) {}

  static create(props: NewTaskProps): Task {
    return new Task(
      requireText(props.id, 'Task id'),
      requireText(props.projectId, 'Project id'),
      requireText(props.title, 'Task title'),
      props.description.trim(),
      props.dueDate,
      props.status,
    );
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | undefined {
    return this.assignee;
  }

  assignTo(userId: string): void {
    this.assignee = requireText(userId, 'Assignee id');
  }

  markDone(): void {
    if (this.currentStatus === 'done') {
      throw new ConflictError(`Task '${this.id}' is already done`);
    }
    this.currentStatus = 'done';
  }
}

